theorem prime_order_element_of_dvd_card {G : Type*} [CommGroup G] [Fintype G] {p : ℕ}
    (hp : Nat.Prime p) (hdiv : p ∣ Fintype.card G) :
    ∃ x : G, orderOf x = p

theorem rational_sum_sq_mul {n m : ℤ} {r s u v : ℚ}
  (hn : r ^ 2 + s ^ 2 = n) (hm : u ^ 2 + v ^ 2 = m) :
  ∃ x y : ℚ, x ^ 2 + y ^ 2 = (n * m : ℚ)

theorem local_open_neighborhoods_eq_sUnion (X : Type*) [TopologicalSpace X] (A : Set X)
  (h1 : ∀ x ∈ A, ∃ U : Set X, x ∈ U ∧ IsOpen U ∧ U ⊆ A) :
  A = ⋃₀ {U : Set X | IsOpen U ∧ U ⊆ A}

theorem closed_restricted_eq {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {s : Set X} {f g : X → Y}
  (hs : IsClosed s) (hf : Continuous f) (hg : Continuous g) :
  IsClosed {x | x ∈ s ∧ f x = g x}

theorem finite_joint_equality_isClosed {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {n : ℕ} {f g : Fin n → X → Y}
  (hf : ∀ i, Continuous (f i)) (hg : ∀ i, Continuous (g i)) :
  IsClosed {x | ∀ i, f i x = g i x}

theorem closed_restricted_le {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {s : Set X} {f g : X → Y}
  (hs : IsClosed s) (hf : Continuous f) (hg : Continuous g) :
  IsClosed {x | x ∈ s ∧ f x ≤ g x}

theorem boolean_ring_product_order_closed {X R : Type*} [TopologicalSpace X] [TopologicalSpace R]
  [Ring R] [LinearOrder R] [OrderTopology R] {s : Set X} {f g : X → R}
  (hR : ∀ a : R, a ^ 2 = a) (hs : IsClosed s)
  (hfg : Continuous (fun x => f x * g x)) :
  IsClosed {x | x ∈ s ∧ f x * g x ≤ g x * f x}

theorem finite_joint_comparison_isClosed {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {n : ℕ} {f g : Fin n → X → Y}
  (hf : ∀ i, Continuous (f i)) (hg : ∀ i, Continuous (g i)) :
  IsClosed {x | ∀ i, f i x ≤ g i x}

theorem closed_order_region_on_closed_set {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {s : Set X} {f g : X → Y}
  (hs : IsClosed s) (hf : ContinuousOn f s) (hg : ContinuousOn g s) :
  IsClosed {x ∈ s | f x ≤ g x}

theorem continuous_eq_set_closed {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {f g : X → Y}
  (hf : Continuous f) (hg : Continuous g) :
  IsClosed {x | f x = g x}

theorem closed_le_and_open_lt {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {f g : X → Y}
  (hf : Continuous f) (hg : Continuous g) :
  IsClosed {x | f x ≤ g x} ∧ IsOpen {x | f x < g x}

theorem equality_and_bound_closed {X Y : Type*} [TopologicalSpace X] [TopologicalSpace Y]
  [LinearOrder Y] [OrderTopology Y] {f g h : X → Y}
  (hf : Continuous f) (hg : Continuous g) (hh : Continuous h) :
  IsClosed {x | f x = g x ∧ g x ≤ h x}
